-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.card_states (
  user_id uuid default auth.uid() not null,
  note_guid text not null,
  ord smallint not null,
  deck_id text not null,
  phase text default 'new'::text not null,
  interday boolean default false not null,
  remaining_steps smallint default 0 not null,
  due timestamp with time zone,
  interval integer default 0 not null,
  stability real,
  difficulty real,
  reps integer default 0 not null,
  lapses integer default 0 not null,
  last_review timestamp with time zone,
  flag smallint default 0 not null,
  suspended boolean default false not null,
  buried_until timestamp with time zone,
  leech boolean default false not null,
  updated_at timestamp with time zone default now() not null,
  retired_at timestamp with time zone,
  constraint card_states_pkey PRIMARY KEY (user_id, note_guid, ord),
  constraint card_states_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint card_states_check CHECK (((phase = 'new'::text) OR ((due IS NOT NULL) AND (last_review IS NOT NULL)))),
  constraint card_states_check1 CHECK (((phase <> 'review'::text) OR interday)),
  constraint card_states_deck_id_check CHECK ((deck_id ~ '^[0-9]{1,20}$'::text)),
  constraint card_states_difficulty_check CHECK (((difficulty >= (1)::double precision) AND (difficulty <= (10)::double precision))),
  constraint card_states_flag_check CHECK (((flag >= 0) AND (flag <= 7))),
  constraint card_states_interval_check CHECK ((("interval" >= 0) AND ("interval" <= 36500))),
  constraint card_states_lapses_check CHECK ((lapses >= 0)),
  constraint card_states_note_guid_check CHECK ((note_guid ~ '^[\x21-\x7e]{1,64}$'::text)),
  constraint card_states_ord_check CHECK (((ord >= 0) AND (ord <= 9999))),
  constraint card_states_phase_check CHECK ((phase = ANY (ARRAY['new'::text, 'learning'::text, 'review'::text, 'relearning'::text]))),
  constraint card_states_remaining_steps_check CHECK (((remaining_steps >= 0) AND (remaining_steps <= 9999))),
  constraint card_states_reps_check CHECK ((reps >= 0)),
  constraint card_states_stability_check CHECK (((stability > (0)::double precision) AND (stability <= (36500)::double precision)))
);

CREATE INDEX card_states_deck ON public.card_states USING btree (user_id, deck_id);

CREATE TRIGGER card_rows_from_a_page_behind AFTER INSERT ON public.card_states FOR EACH ROW EXECUTE FUNCTION public.card_rows_from_a_page_behind();
CREATE TRIGGER quota_cards AFTER INSERT OR DELETE ON public.card_states FOR EACH ROW EXECUTE FUNCTION public.quota_cards();

alter table public.card_states enable row level security;

create policy "own card states" on public.card_states
  as permissive
  for all
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)))
  with check (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant select on table public.card_states to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.card_states to service_role;
